final class Faluss_Identity_Client_Schema {
 const VERSION='1'; const OPTION='faluss_identity_client_schema_version';
 public static function schema(){return array('links'=>array('suffix'=>'faluss_identity_links','columns'=>array('id'=>'bigint(20) unsigned NOT NULL AUTO_INCREMENT','wp_user_id'=>'bigint(20) unsigned NOT NULL','faluss_id'=>'char(36) NOT NULL','created_at'=>'datetime NOT NULL','last_proved_at'=>'datetime NOT NULL'),'indexes'=>array('PRIMARY KEY (`id`)','UNIQUE KEY `wp_user_id_unique` (`wp_user_id`)','UNIQUE KEY `faluss_id_unique` (`faluss_id`)')),'states'=>array('suffix'=>'faluss_identity_client_state','columns'=>array('id'=>'bigint(20) unsigned NOT NULL AUTO_INCREMENT','state_hash'=>'char(64) NOT NULL','browser_hash'=>'char(64) NOT NULL','redirect_url'=>'varchar(2048) NOT NULL','flow_mode'=>'varchar(20) NOT NULL','wp_user_id'=>'bigint(20) unsigned NULL','expires_at'=>'datetime NOT NULL','consumed_at'=>'datetime NULL','created_at'=>'datetime NOT NULL'),'indexes'=>array('PRIMARY KEY (`id`)','UNIQUE KEY `state_hash_unique` (`state_hash`)','KEY `expires_at` (`expires_at`)')));}
 public static function tables(){global $wpdb;$out=array();if(!is_object($wpdb)||empty($wpdb->prefix)||1!==preg_match('/^[A-Za-z0-9_]+$/',$wpdb->prefix)){return $out;}foreach(self::schema() as $key=>$def){$out[$key]=$wpdb->prefix.$def['suffix'];}return $out;}
 public static function install_or_verify(){global $wpdb;if(!is_object($wpdb)||!method_exists($wpdb,'get_charset_collate'))return false;$tables=self::tables();if(count($tables)!==2)return false;foreach(self::schema() as $key=>$def){$cols=implode(', ',array_map(fn($n,$d)=>'`'.$n.'` '.$d,array_keys($def['columns']),$def['columns']));$sql='CREATE TABLE IF NOT EXISTS `'.$tables[$key].'` ('.$cols.', '.implode(', ',$def['indexes']).') ENGINE=InnoDB '.$wpdb->get_charset_collate();if(false===$wpdb->query($sql))return false;}update_option(self::OPTION,self::VERSION,false);return true;}
}
